const pristinePopulation=()=>{const m=r.loadManifest().manifest,e={billMismatches:6,paymentMismatches:2,bills:m.transactions.filter(x=>x.record_type==='BILL').map(x=>({id:x.record_id,company_id:x.expected_company_id,vendor_id:x.expected_current_vendor_id})),payments:m.transactions.filter(x=>x.record_type==='VENDOR_PAYMENT').map(x=>({id:x.record_id,company_id:x.expected_company_id,vendor_id:x.expected_current_vendor_id,bill_id:null})),equivalentTargetVendors:[],fingerprint:null};e.fingerprint=populationFingerprint(e);return e};
