const repairedPopulation=()=>{const m=r.loadManifest().manifest,base=pristinePopulation(),ids=new Map(m.groups.map((g,i)=>[g.group_id,100+i])),equivalentTargetVendors=m.groups.map(g=>({groupId:g.group_id,sourceVendorId:g.source_vendor_id,sourceCompanyId:g.source_vendor_company_id,targetCompanyId:g.target_company_id,equivalentVendorId:ids.get(g.group_id),sourceFingerprint:'a'.repeat(64),equivalentFingerprint:'a'.repeat(64)})),bills=base.bills.map(b=>{const g=m.groups.find(g=>g.records.some(x=>x.record_type==='BILL'&&x.record_id===b.id));return{...b,vendor_id:ids.get(g.group_id)}}),payments=base.payments.map(p=>({...p,vendor_id:ids.get('G2')}));return sealPopulation({...base,billMismatches:0,paymentMismatches:0,bills,payments,equivalentTargetVendors})};
