test('strict G1-G2 valid payment path uses shared numeric vendor id',async()=>{const full=r.loadManifest().manifest,m={groups:full.groups.slice(0,2),transactions:full.transactions.filter(t=>['G1','G2'].includes(t.group_id))},a=new StatefulFakeAdapter(full,{strictTyped:true}),seen=[];a.insertVendorCopy=async(src,c)=>({operationType:'VENDOR_INSERT',table:'vendors',groupId:c===6?'G1':'G2',recordId:c===6?100:101,companyId:c,sourceVendorId:1,copiedFingerprint:'a'.repeat(64)});const ub=a.updateBillVendor.bind(a),up=a.updateVendorPaymentVendor.bind(a);a.updateBillVendor=async(...x)=>{seen.push(x[3]);const id=x[0]===3?100:101;return {operationType:'BILL_UPDATE',table:'bills',groupId:x[0]===3?'G1':'G2',recordId:x[0],companyId:x[1],oldVendorId:x[2],newVendorId:id,affectedRows:1}};a.updateVendorPaymentVendor=async(...x)=>{seen.push(x[3]);return {operationType:'VENDOR_PAYMENT_UPDATE',table:'vendor_payments',groupId:'G2',recordId:x[0],companyId:7,oldVendorId:1,newVendorId:101,affectedRows:1}};await r.executeRepair(a,m,{requireTypedEvidence:true});assert.ok(seen.every(Number.isInteger));assert.equal(a.state.vendorPayments[1].bill_id,null);assert.equal(a.state.vendorPayments[2].bill_id,null);});
test('strict G1-G2-G3 valid multi-bill path commits G3 atomically',async()=>{const full=r.loadManifest().manifest,m={groups:full.groups.slice(0,3),transactions:full.transactions.filter(t=>['G1','G2','G3'].includes(t.group_id))},a=new StatefulFakeAdapter(full,{strictTyped:true}),seen=[];a.insertVendorCopy=async(src,c)=>{const id=c===6?100:c===7?101:102;return {operationType:'VENDOR_INSERT',table:'vendors',groupId:c===6?'G1':c===7?'G2':'G3',recordId:id,companyId:c,sourceVendorId:c===4?3:1,copiedFingerprint:'a'.repeat(64)}};a.updateBillVendor=async(i,c,o,n)=>{seen.push(n);return {operationType:'BILL_UPDATE',table:'bills',groupId:i<=3?'G1':i===4?'G2':'G3',recordId:i,companyId:c,oldVendorId:o,newVendorId:i<=3?100:i===4?101:102,affectedRows:1}};a.updateVendorPaymentVendor=async(i,c,o,n)=>({operationType:'VENDOR_PAYMENT_UPDATE',table:'vendor_payments',groupId:'G2',recordId:i,companyId:c,oldVendorId:o,newVendorId:101,affectedRows:1});await r.executeRepair(a,m,{requireTypedEvidence:true});assert.deepEqual(seen.slice(-2),[102,102]);assert.ok(seen.every(Number.isInteger));});
