test('native G2 reused Vendor-1 drift control',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});a.sourceInjection={groupId:'G2',sourceVendorId:1,phase:'BEFORE_COMMIT',mode:'protected_field_drift'};await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true}),e=>e.code==='SOURCE_VENDOR_DRIFT'||e.code==='SOURCE_VENDOR_EVIDENCE_INVALID');const g1=a._sourceReadLog.filter(x=>x.groupId==='G1'),g2=a._sourceReadLog.filter(x=>x.groupId==='G2');assert.equal(g1.length,2);assert.equal(g2.length,2);assert.equal(g1[0].phase,'BASELINE');assert.equal(g2[0].phase,'BASELINE');assert.ok(g2[1].stagedMutationCount>0);assert.equal(a.getCommittedCount('VENDOR_INSERT'),1);assert.equal(a.getCommittedCount('BILL_UPDATE'),1);assert.equal(a.getCommittedCount('VENDOR_PAYMENT_UPDATE'),0);assert.equal(a.activeTransaction,null)});
test('native G5 Vendor-5 drift preserves G1-G4',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});a.sourceInjection={groupId:'G5',sourceVendorId:5,phase:'BEFORE_COMMIT',mode:'fingerprint_drift'};const before=a.snapshot();await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true}),e=>e.code==='SOURCE_VENDOR_DRIFT'||e.code==='SOURCE_VENDOR_EVIDENCE_INVALID');assert.equal(a.getCommittedCount('VENDOR_INSERT'),4);assert.equal(a.getCommittedCount('BILL_UPDATE'),5);assert.equal(a.getCommittedCount('VENDOR_PAYMENT_UPDATE'),2);assert.equal(a.getRolledBackCount('VENDOR_INSERT'),1);assert.equal(a.state.bills[8].vendor_id,before.bills[8].vendor_id);assert.equal(a.state.vendors[104],undefined);assert.equal(a.activeTransaction,null)});
test('strict Bill-3 baseline evidence matrix',async()=>{const m=r.loadManifest().manifest,probe=new StatefulFakeAdapter(m,{strictTyped:true}),good=await probe.getBillEvidence(3);const cases=[['throw',async()=>{throw Error('BILL_GETTER')}],['undefined',undefined],['null',null],['primitive',1],['array',[]],['empty',{}],['recordType',{...good,recordType:'X'}],['recordId',{...good,recordId:9}],['company',{...good,companyId:9}],['vendor',{...good,vendorId:9}],['missingFields',{...good,protectedFields:{}}],['badFp',{...good,fingerprint:'X'}],['upper',{...good,fingerprint:good.fingerprint.toUpperCase()}],['short',{...good,fingerprint:good.fingerprint.slice(1)}],['nonhex',{...good,fingerprint:'z'.repeat(64)}],['mismatch',{...good,protectedFields:{x:1}}]];for(const [name,e] of cases){const a=new StatefulFakeAdapter(m,{strictTyped:true});a.getBillEvidence=async()=>typeof e==='function'?e():e;await assert.rejects(r.executeRepair(a,{groups:[m.groups[0]],transactions:[m.transactions[0]]},{requireTypedEvidence:true}),e=>e.code==='BILL_EVIDENCE_INVALID'||e.message==='BILL_GETTER',name);assert.equal(a.committed.length,0);assert.equal(a.activeTransaction,null)}const a=new StatefulFakeAdapter(m,{strictTyped:true});await r.executeRepair(a,{groups:[m.groups[0]],transactions:[m.transactions[0]]},{requireTypedEvidence:true});assert.equal(a.getCommittedCount('VENDOR_INSERT'),1)});
test('native G3 Bill-6 invalid pre-state atomicity',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});const good=a.getBillEvidence.bind(a);a.getBillEvidence=async id=>{const e=await good(id);return id===6?{...e,companyId:999}:e};await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true}),e=>e.code==='BILL_EVIDENCE_INVALID');assert.equal(a.getCommittedCount('VENDOR_INSERT'),2);assert.equal(a.getCommittedCount('BILL_UPDATE'),2);assert.equal(a.getRolledBackCount('VENDOR_INSERT'),0);assert.equal(a.state.bills[5].vendor_id,3);assert.equal(a.state.bills[6].vendor_id,3);assert.equal(a.activeTransaction,null)});


test('native G5 Bill-8 invalid pre-state preserves G1-G4',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});const good=a.getBillEvidence.bind(a);a.getBillEvidence=async id=>{const e=await good(id);return id===8?{...e,companyId:999}:e};const before=a.snapshot();await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true}),e=>e.code==='BILL_EVIDENCE_INVALID');assert.equal(a.getCommittedCount('VENDOR_INSERT'),4);assert.equal(a.getCommittedCount('BILL_UPDATE'),5);assert.equal(a.getCommittedCount('VENDOR_PAYMENT_UPDATE'),2);assert.equal(a.state.bills[8].vendor_id,before.bills[8].vendor_id);assert.equal(a.state.vendors[104],undefined);assert.equal(a.activeTransaction,null)});
test('bill evidence injection timing is scoped',async()=>{const f=r.loadManifest().manifest,m={groups:f.groups.slice(0,3),transactions:f.transactions.filter(t=>[3,4,5,6,1,2].includes(t.record_id))},a=new StatefulFakeAdapter(m,{strictTyped:true});a.billInjection={groupId:'G3',recordId:6,phase:'BEFORE_COMMIT',mode:'wrong_vendor'};await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true,requireBillPostState:true}));const g3=a._billReadLog.filter(x=>x.groupId==='G3');assert.equal(g3.filter(x=>x.recordId===5).length,2);assert.equal(g3.filter(x=>x.recordId===6).length,2);assert.equal(g3[0].phase,'BASELINE');assert.ok(g3.some(x=>x.phase==='BEFORE_COMMIT'&&x.stagedMutationCount>0))});
test('G1 Bill-3 final drift matrix',async()=>{const m=r.loadManifest().manifest;for(const mode of ['throw','disappear','malformed','wrong_record','wrong_company','wrong_vendor','fingerprint_drift','protected_field_drift','fingerprint_mismatch']){const a=new StatefulFakeAdapter(m,{strictTyped:true});a.billInjection={groupId:'G1',recordId:3,phase:'BEFORE_COMMIT',mode};const before=a.snapshot();await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true,requireBillPostState:true}),e=>e.code==='BILL_DRIFT',mode);assert.equal(a.getCommittedCount('VENDOR_INSERT'),0);assert.equal(a.state.bills[3].vendor_id,before.bills[3].vendor_id);assert.equal(a.activeTransaction,null)}const a=new StatefulFakeAdapter(m,{strictTyped:true});await r.executeRepair(a,m,{requireTypedEvidence:true,requireBillPostState:true});assert.equal(a.state.bills[3].vendor_id,100)});
test('G3 Bill-6 post-state drift rolls back G3 atomically',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});a.billInjection={groupId:'G3',recordId:6,phase:'BEFORE_COMMIT',mode:'protected_field_drift'};const before=a.snapshot();await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true,requireBillPostState:true}),e=>e.code==='BILL_DRIFT');assert.equal(a.getCommittedCount('VENDOR_INSERT'),2);assert.equal(a.getCommittedCount('BILL_UPDATE'),2);assert.equal(a.getCommittedCount('VENDOR_PAYMENT_UPDATE'),2);assert.equal(a.state.bills[5].vendor_id,before.bills[5].vendor_id);assert.equal(a.state.bills[6].vendor_id,before.bills[6].vendor_id);assert.equal(a.state.vendors[102],undefined);assert.equal(a.activeTransaction,null)});
test('G5 Bill-8 post-state drift preserves G1-G4',async()=>{const m=r.loadManifest().manifest,a=new StatefulFakeAdapter(m,{strictTyped:true});a.billInjection={groupId:'G5',recordId:8,phase:'BEFORE_COMMIT',mode:'wrong_vendor'};const before=a.snapshot();await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true,requireBillPostState:true}),e=>e.code==='BILL_DRIFT');assert.equal(a.getCommittedCount('VENDOR_INSERT'),4);assert.equal(a.getCommittedCount('BILL_UPDATE'),5);assert.equal(a.getCommittedCount('VENDOR_PAYMENT_UPDATE'),2);assert.equal(a.state.bills[8].vendor_id,before.bills[8].vendor_id);assert.equal(a.state.vendors[104],undefined);assert.equal(a.activeTransaction,null)});
test('payment evidence injection timing is scoped',async()=>{const f=r.loadManifest().manifest,m={groups:f.groups.slice(0,2),transactions:f.transactions.filter(t=>[1,2,3,4].includes(t.record_id))},a=new StatefulFakeAdapter(m,{strictTyped:true});a.paymentInjection={groupId:'G2',recordId:2,phase:'BEFORE_COMMIT',mode:'wrong_vendor'};await assert.rejects(r.executeRepair(a,m,{requireTypedEvidence:true,requirePaymentPostState:true}));const p1=a._paymentReadLog.filter(x=>x.recordId===1),p2=a._paymentReadLog.filter(x=>x.recordId===2);assert.equal(p1.length,2);assert.equal(p2.length,2);assert.equal(p1[0].phase,'BASELINE');assert.equal(p2[0].phase,'BASELINE');assert.ok(p1[1].stagedMutationCount>0);assert.ok(p2[1].stagedMutationCount>0)});
